<?php
declare(strict_types=1);
use App\Support\Html;
use App\Support\Language;
/** @var Language $lang */
/** @var list<array<string,mixed>> $activity */
/** @var array{source:string,last_sync:?string} $provenance */
$mergedVisible = count(array_filter(
    $activity,
    static fn(array $entry): bool => ($entry['kind'] ?? null) === 'pr' && ($entry['state'] ?? null) === 'merged',
));
$stateLabels = [
    'merged' => $lang->value('Sloučeno', 'Merged'),
    'completed' => $lang->value('Dokončeno', 'Completed'),
    'open' => $lang->value('Otevřeno', 'Open'),
    'closed' => $lang->value('Uzavřeno', 'Closed'),
];
?>
<section class="page-hero shell"><h1><?= $lang->value('Open source','Open-source contributions') ?></h1><p><?= $lang->value('Opravy a hlášení v CakePHP, Rectoru a dalších projektech. U každého příspěvku najdeš jeho stav a odkaz na původní změnu nebo diskusi.', 'Selected pull requests and bug reports in projects including CakePHP, Rector and PHPStan. Each entry links to the original discussion or change.') ?></p></section>
<section class="shell section"><div class="contribution-intro"><div><strong><?= $mergedVisible ?></strong><span><?= $lang->value('sloučených pull requestů v tomto přehledu','merged pull requests in this overview') ?></span></div><p><?= $provenance['source'] === 'github-public-api'
    ? $lang->value('Seznam pochází z posledního úspěšného veřejného importu GitHubu.', 'Entries are from the last successful public GitHub import.')
    : ($provenance['source'] === 'unavailable'
        ? $lang->value('GitHub data jsou dočasně nedostupná. Historické záznamy nezveřejňujeme jako náhradu.', 'GitHub data is temporarily unavailable. Historical records are not republished as a fallback.')
        : $lang->value('Zobrazený je ručně ověřený historický snímek. Automatický import není potvrzen.', 'This is a hand-reviewed historical snapshot. An automated import is not confirmed.')) ?><?php if ($provenance['last_sync'] !== null): ?><br><time><?= $lang->value('Poslední úspěšný import: ', 'Last successful import: ') ?><?= Html::escape($provenance['last_sync']) ?></time><?php endif; ?></p></div>
<details class="activity-reading">
    <summary><?= $lang->value('Jak číst stav a datum příspěvku', 'How to read contribution status and dates') ?></summary>
    <dl>
        <div><dt><?= $lang->value('Založeno', 'Created') ?></dt><dd><?= $lang->value('Den, kdy vznikl pull request nebo hlášení.', 'The date the pull request or issue was opened.') ?></dd></div>
        <div><dt><?= $lang->value('Sloučeno', 'Merged') ?></dt><dd><?= $lang->value('Den, kdy správci přijali změnu do projektu.', 'The date maintainers accepted the change into the project.') ?></dd></div>
        <div><dt><?= $lang->value('Dokončeno', 'Completed') ?></dt><dd><?= $lang->value('Hlášení nebo požadavek s doloženým dokončením.', 'An issue or task confirmed as completed.') ?></dd></div>
        <div><dt><?= $lang->value('Uzavřeno', 'Closed') ?></dt><dd><?= $lang->value('Den uzavření bez potvrzeného dokončení nebo s neznámým důvodem.', 'The date the item was closed without confirmed completion or with an unknown reason.') ?></dd></div>
    </dl>
</details>
<div data-activity-browser><div class="filter-bar"><label class="search-field"><span class="visually-hidden"><?= $lang->value('Hledat příspěvky', 'Search contributions') ?></span><span aria-hidden="true">⌕</span><input type="search" data-search placeholder="<?= $lang->value('Hledat repozitář nebo změnu…','Search repository or change…') ?>"></label><select data-state aria-label="<?= $lang->value('Stav', 'Status') ?>"><option value="all"><?= $lang->value('Všechny stavy','All statuses') ?></option><option value="merged"><?= $stateLabels['merged'] ?></option><option value="completed"><?= $stateLabels['completed'] ?></option><option value="open"><?= $stateLabels['open'] ?></option><option value="closed"><?= $stateLabels['closed'] ?></option></select><select data-kind aria-label="<?= $lang->value('Typ příspěvku', 'Contribution type') ?>"><option value="all">PR + Issues</option><option value="pr">Pull Requests</option><option value="issue">Issues</option></select><button class="btn btn-ghost btn-sm" type="button" data-filter-reset hidden><?= $lang->value('Vymazat filtry', 'Clear filters') ?></button><span class="filter-count" data-count role="status" aria-live="polite" aria-atomic="true"><?= count($activity) ?> <?= $lang->value(count($activity) === 1 ? 'záznam' : (count($activity) >= 2 && count($activity) <= 4 ? 'záznamy' : 'záznamů'), count($activity) === 1 ? 'result' : 'results') ?></span></div><div class="activity-list">
<?php foreach ($activity as $item): $url = Html::safeUrl((string)($item['source_url'] ?? '')); $state = (string)($item['state'] ?? ''); $stateLabel = match ($state) { 'completed' => $lang->value('Dokončeno','Completed'), 'merged' => $lang->value('Sloučeno','Merged'), 'open' => $lang->value('Otevřeno','Open'), 'closed' => $lang->value('Uzavřeno · důvod neznámý','Closed · reason unknown'), default => $stateLabels[$state] ?? $state }; $statusClass = $state; $closedTooltip = $state === 'closed' ? $lang->value('GitHub API neuvádí důvod uzavření (state_reason), nebo byl issue uzavřen bez dokončení.', 'GitHub API does not specify a close reason (state_reason), or the issue was closed without completion.') : ''; ?><article class="activity-item" data-activity data-state="<?= Html::escape($state) ?>" data-kind="<?= Html::escape((string)($item['kind']??'')) ?>" data-search-text="<?= Html::escape(strtolower((string)$item['repository'].' '.(string)$item['title'])) ?>"><span class="activity-icon"><?= ($item['kind'] ?? '') === 'issue' ? '#' : '↳' ?></span><div class="activity-body"><div class="activity-repo"><?= Html::escape((string)$item['repository']) ?> <span>· <?= Html::escape((string)$item['kind']) ?></span></div><strong><?= Html::escape((string)$item['title']) ?></strong></div><div class="activity-side"><span class="status <?= Html::escape($statusClass) ?>"<?= $state === 'closed' ? ' title="' . Html::escape($closedTooltip) . '" tabindex="0"' : '' ?>><?= Html::escape($stateLabel) ?></span><span class="activity-dates"><span><?= $lang->value('Založeno','Created') ?> <time><?= Html::escape(substr((string)$item['published_at'],0,10)) ?></time></span><?php if (!empty($item['merged_at'])): ?><span><?= $lang->value('Sloučeno','Merged') ?> <time><?= Html::escape(substr((string)$item['merged_at'],0,10)) ?></time></span><?php elseif (!empty($item['closed_at'])): ?><span><?= $state === 'completed' ? $lang->value('Dokončeno','Completed') : $lang->value('Uzavřeno','Closed') ?> <time><?= Html::escape(substr((string)$item['closed_at'],0,10)) ?></time></span><?php endif; ?></span></div><div class="activity-actions"><button class="mini-button" type="button" data-activity-inspect data-inspect-title="<?= Html::escape((string)$item['title']) ?>" data-inspect-repo="<?= Html::escape((string)$item['repository']) ?>" data-inspect-state="<?= Html::escape($stateLabel) ?>" data-inspect-url="<?= Html::escape($url) ?>"><?= $lang->value('Detail','Inspect') ?></button><a class="activity-arrow" href="<?= Html::escape($url) ?>" aria-label="<?= $lang->value('Otevřít na GitHubu', 'Open on GitHub') ?>" target="_blank" rel="noopener noreferrer">↗</a></div></article><?php endforeach; ?>
</div><p class="empty-state hidden" data-empty><?= $lang->value('Nic nebylo nalezeno.','No matching activity.') ?></p></div><dialog class="activity-dialog" data-activity-dialog aria-labelledby="activity-dialog-title"><form method="dialog"><button class="mini-button dialog-close" aria-label="<?= $lang->value('Zavřít', 'Close') ?>">✕</button></form><span class="eyebrow"><?= $lang->value('PŘÍSPĚVEK / ZDROJ', 'UPSTREAM CHANGE / SOURCE RECORD') ?></span><h2 id="activity-dialog-title" data-activity-title></h2><p class="activity-dialog-repo" data-activity-repo></p><p><?= $lang->value('Podrobnosti, diskusi a aktuální stav příspěvku najdeš na GitHubu.','Find the details, discussion and current status of this contribution on GitHub.') ?></p><a class="btn btn-primary" data-activity-url target="_blank" rel="noopener noreferrer" href="#"><?= $lang->value('Otevřít na GitHubu','Open on GitHub') ?> ↗</a></dialog></section>
